/* Scholara animated logo — <scholara-logo></scholara-logo>  (add the `static` attribute for a still logo) */
(()=>{
const PT={"bookSpark":{"x":219,"y":16,"w":214,"h":219,"src":"data:image/webp;base64,"},"pageBlue":{"x":66,"y":150,"w":517,"h":218,"src":"data:image/webp;base64,"},"pagePink":{"x":14,"y":239,"w":621,"h":179,"src":"data:image/webp;base64,"},"S":{"x":647,"y":78,"w":231,"h":308,"src":"data:image/webp;base64,"},"c":{"x":868,"y":171,"w":198,"h":221,"src":"data:image/webp;base64,"},"iDot":{"x":1068,"y":88,"w":77,"h":63,"src":"data:image/webp;base64,"},"h":{"x":1065,"y":149,"w":209,"h":237,"src":"data:image/webp;base64,"},"spark":{"x":1274,"y":165,"w":213,"h":219,"src":"data:image/webp;base64,"},"l":{"x":1484,"y":79,"w":81,"h":214,"src":"data:image/webp;base64,"},"lDot":{"x":1487,"y":283,"w":76,"h":103,"src":"data:image/webp;base64,"},"a1":{"x":1568,"y":168,"w":208,"h":224,"src":"data:image/webp;base64,"},"r":{"x":1777,"y":169,"w":153,"h":216,"src":"data:image/webp;base64,"},"a2":{"x":1914,"y":169,"w":207,"h":223,"src":"data:image/webp;base64,"}};
const W=2135,H=435,GROUP=['pagePink','pageBlue','bookSpark','S','c','h','iDot','l','lDot','a1','r','a2'];
const C={};for(const n in PT){const p=PT[n];C[n]=[p.x+p.w/2,p.y+p.h/2]}
const SL=C.spark,GOLD='#FCB201',END=4400;
const PAL=['#FF4F54','#FA019F','#018FFC','#FCB201','#01BBBB','#FC8301'];
function mkNet(X0,X1,Y0,Y1,Cc,Rr,seed){const R=rng(seed),N=[];const cw=(X1-X0)/Cc,rh=(Y1-Y0)/Rr;for(let r=0;r<Rr;r++)for(let c=0;c<Cc;c++){const x=X0+(c+.15+.7*R())*cw,y=Y0+(r+.15+.7*R())*rh;N.push({x,y,ph:R()*6.283,amp:10+R()*16,c:PAL[Math.floor(R()*6)],dim:(x>600&&x<2150&&y>60&&y<410)?.45:1,T:3460+Math.hypot(x-SL[0],(y-SL[1])*1.8)*.7})}
const L=[];N.forEach((n,i)=>{N.map((m,j)=>[j,Math.hypot(n.x-m.x,n.y-m.y)]).filter(([j])=>j!==i).sort((p,q)=>p[1]-q[1]).slice(0,2).forEach(([j,d])=>{if(d<330&&!L.some(l=>(l[0]===i&&l[1]===j)||(l[0]===j&&l[1]===i)))L.push([i,j])})});return{N,L}}
function drawNet(net,t,g){const pos=net.N.map(n=>({p:E.back(pr(t,n.T,n.T+520)),x:n.x+Math.sin(t/1300+n.ph)*n.amp,y:n.y+Math.cos(t/1700+n.ph)*n.amp*.6}));
 for(const[i,j]of net.L){const a=net.N[i],b=net.N[j];const q=pr(t,Math.min(a.T,b.T)+260,Math.max(a.T,b.T)+420);if(q<=0)continue;const[s,e,f]=a.T<=b.T?[pos[i],pos[j],a]:[pos[j],pos[i],b];g.line(s.x,s.y,lerp(s.x,e.x,E.out(q)),lerp(s.y,e.y,E.out(q)),f.c,.55*Math.min(a.dim,b.dim),2.4)}
 net.N.forEach((n,i)=>{const p=pos[i];if(p.p>0)g.dot(p.x,p.y,(9+2.5*Math.sin(t/600+n.ph))*p.p,n.c,.9*n.dim*Math.min(1,p.p))})}
const cl=(v,a=0,b=1)=>Math.min(b,Math.max(a,v)),pr=(t,a,b)=>cl((t-a)/(b-a)),lerp=(a,b,p)=>a+(b-a)*p;
const E={out:p=>1-(1-p)**3,io:p=>p<.5?4*p*p*p:1-((-2*p+2)**3)/2,back:p=>{const c=1.9,c3=c+1;return 1+c3*(p-1)**3+c*(p-1)**2}};
const bump=(t,a,d)=>{const p=(t-a)/d;return p<0||p>1?0:Math.sin(Math.PI*p)};
const rng=s=>()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
const sAt=(X,Y)=>({x:X-SL[0],y:Y-SL[1]});
const lit=(t,T)=>{const p=pr(t,T,T+240);return{o:.16+.84*p,f:p<1?`grayscale(${1-p})`:''}};
const glow=(t,T,d,k)=>{const b=bump(t,T,d);return b>0?`drop-shadow(0 0 ${b*34*k}px rgba(252,178,1,.95))`:''};
function arcs(t,segs){for(let i=0;i<segs.length;i++){const[f,to,a,b,h]=segs[i];if(t<b){const p=pr(t,a,b);return[lerp(f[0],to[0],p),lerp(f[1],to[1],p)-h*4*p*(1-p),i,p]}}const l=segs[segs.length-1];return[l[1][0],l[1][1],segs.length,1]}
function chain(s,list){let f=s;return list.map(([to,a,b,h])=>{const r=[f,to,a,b,h];f=to;return r})}
const HOPS=chain([C.bookSpark[0],C.bookSpark[1]-34],[[[762,22],1300,1760,170],[[967,116],1760,2110,120],[[1106,32],2110,2460,120],[[1524,22],2460,2920,190],[SL,2920,3460,150]]);
function render(t,g,k){const o={};
 const pp=pr(t,0,650),pb=pr(t,150,800);
 o.pagePink={y:140*(1-E.back(pp)),o:pp};o.pageBlue={y:140*(1-E.back(pb)),o:pb};
 const bs=pr(t,520,950);o.bookSpark={s:E.back(bs)*(1+.18*bump(t,1100,320)+.2*bump(t,3560,420)),r:-90*(1-bs),o:bs?1:0};
 const lt={S:1760,c:2110,h:2460,iDot:2460,l:2920,lDot:2920,a1:3540,r:3620,a2:3700};
 for(const n in lt)o[n]=lit(t,lt[n]);
 for(const n of['S','c','h','l']){const b=bump(t,lt[n],320);o[n].sy=1-.17*b;o[n].sx=1+.07*b}
 o.iDot.y=-90*bump(t,2460,560);o.iDot.r=28*bump(t,2460,560);o.lDot.y=14*bump(t,2920,300);
 for(const n of['a1','r','a2'])o[n].y=-34*bump(t,lt[n],420);
 if(t<1100)o.spark={o:0};
 else if(t<1300){const p=E.out(pr(t,1100,1300));o.spark={...sAt(C.bookSpark[0],C.bookSpark[1]-34*p),s:lerp(.95,.5,p)}}
 else{const[X,Y,i,p]=arcs(t,HOPS);
  o.spark={...sAt(X,Y),s:i<4?.5:i===4?lerp(.5,1,E.io(p)):1,r:i<4?90*i+90*E.io(p):360+360*E.io(p)};
  if(t>=3460){const b=bump(t,3460,280);o.spark.sy=1-.2*b;o.spark.sx=1+.12*b;o.spark.f=glow(t,3440,900,k)}
  if(t<3460)for(let j=1;j<=14;j++){const tt=t-j*20;if(tt<1300)break;const[x,y]=arcs(tt,HOPS);g.dot(x,y,9*(1-j/15),j%3?GOLD:'#fff',.55*(1-j/15))}}
 g.burst(SL,t,3460,1100,15);
 return o}
const css=`:host{display:block;position:relative;-webkit-tap-highlight-color:transparent}
.f{position:relative;padding-top:8%}:host([static]) .f{padding-top:0}
.s{position:relative;aspect-ratio:2135/435}
img{position:absolute;pointer-events:none;user-select:none;will-change:transform,opacity}
.g img{transform-origin:50% 100%}.sp{transform-origin:50% 50%}
canvas{position:absolute;left:-10%;top:-25%;width:120%;height:150%;pointer-events:none}`;
class ScholaraLogo extends HTMLElement{
 connectedCallback(){if(this.sh)return;this.sh=this.attachShadow({mode:'open'});
  this.setAttribute('role','img');if(!this.hasAttribute('aria-label'))this.setAttribute('aria-label','Scholara');
  this.sh.innerHTML=`<style>${css}</style><div class="f"><canvas></canvas><div class="s"><div class="g"></div></div></div>`;
  const s=this.sh.querySelector('.s'),g=this.sh.querySelector('.g');this.cv=this.sh.querySelector('canvas');this.ctx=this.cv.getContext('2d');this.st=s;this.el={};
  const mk=(n,parent,cls)=>{const p=PT[n],i=new Image();i.src=p.src;i.alt='';i.draggable=false;if(cls)i.className=cls;Object.assign(i.style,{left:p.x/W*100+'%',top:p.y/H*100+'%',width:p.w/W*100+'%'});parent.appendChild(i);this.el[n]=i};
  GROUP.forEach(n=>mk(n,g));mk('spark',s,'sp');
  const still=this.hasAttribute('static')||matchMedia('(prefers-reduced-motion: reduce)').matches;
  this.net=this.hasAttribute('network')&&!this.hasAttribute('static')?mkNet(-20,W+20,-160,H+10,8,3,33):null;
  {const sel=this.getAttribute('bg-target');const tg=sel&&!this.hasAttribute('static')?document.querySelector(sel):null;if(tg){const bc=document.createElement('canvas');bc.setAttribute('aria-hidden','true');Object.assign(bc.style,{position:'absolute',inset:'0',width:'100%',height:'100%',pointerEvents:'none'});tg.prepend(bc);this.bg={tg,bc,bx:bc.getContext('2d'),N:[],L:[]};new ResizeObserver(()=>{this.bgSize();this.draw()}).observe(tg)}}this.t=still?END+3000:0;this.on=false;this.idle=!this.hasAttribute('static');
  new ResizeObserver(()=>{this.size();this.draw()}).observe(this);
  if(!still){new IntersectionObserver((es,ob)=>{if(es[0].isIntersecting){ob.disconnect();this.play()}},{threshold:.3}).observe(this);
   this.addEventListener('click',()=>this.play())}
 }
 bgSize(){const b=this.bg;if(!b)return;const d=Math.min(2,devicePixelRatio||1),w=b.tg.clientWidth,h=b.tg.clientHeight;b.bc.width=w*d;b.bc.height=h*d;b.d=d;b.w=w;b.h=h;
   const tr=b.tg.getBoundingClientRect(),sr=this.st.getBoundingClientRect(),k=sr.width/W;b.ox=sr.left-tr.left+SL[0]*k;b.oy=sr.top-tr.top+SL[1]*k;
   const S=Math.max(170,Math.min(240,w/7)),C=Math.max(3,Math.round(w/S)),R=Math.max(2,Math.round(h/S)),cw=w/C,rh=h/R,r=rng(91),N=[];
   for(let i=0;i<R;i++)for(let j=0;j<C;j++){const x=(j+.15+.7*r())*cw,y=(i+.15+.7*r())*rh;N.push({x,y,ph:r()*6.283,amp:8+r()*14,c:PAL[Math.floor(r()*6)],s:.75+.5*r(),T:3460+Math.hypot(x-b.ox,y-b.oy)*.9})}
   const L=[];N.forEach((n,i)=>{N.map((m,j)=>[j,Math.hypot(n.x-m.x,n.y-m.y)]).filter(([j])=>j!==i).sort((p,q)=>p[1]-q[1]).slice(0,2).forEach(([j,dd])=>{if(dd<S*1.6&&!L.some(l=>(l[0]===i&&l[1]===j)||(l[0]===j&&l[1]===i)))L.push([i,j])})});b.N=N;b.L=L}
 drawBg(t){const b=this.bg;if(!b||!b.N.length)return;const x=b.bx;x.setTransform(b.d,0,0,b.d,0,0);x.clearRect(0,0,b.w,b.h);
   const pos=b.N.map(n=>({p:E.back(pr(t,n.T,n.T+600)),x:n.x+Math.sin(t/1500+n.ph)*n.amp,y:n.y+Math.cos(t/1900+n.ph)*n.amp*.7}));x.lineCap='round';
   for(const[i,j]of b.L){const a=b.N[i],c=b.N[j];const q=pr(t,Math.min(a.T,c.T)+260,Math.max(a.T,c.T)+460);if(q<=0)continue;const[s,e,f]=a.T<=c.T?[pos[i],pos[j],a]:[pos[j],pos[i],c];x.globalAlpha=.28;x.strokeStyle=f.c;x.lineWidth=1.6;x.beginPath();x.moveTo(s.x,s.y);x.lineTo(lerp(s.x,e.x,E.out(q)),lerp(s.y,e.y,E.out(q)));x.stroke()}
   b.N.forEach((n,i)=>{const p=pos[i];if(p.p<=0)return;x.globalAlpha=.6*Math.min(1,p.p);x.fillStyle=n.c;x.beginPath();x.arc(p.x,p.y,Math.max(.5,(4.5+1.2*Math.sin(t/650+n.ph))*n.s*p.p),0,7);x.fill()});x.globalAlpha=1}
 size(){const d=Math.min(2,devicePixelRatio||1);const r=this.cv.getBoundingClientRect();this.cv.width=r.width*d;this.cv.height=r.height*d;this.d=d;this.k=this.st.clientWidth/W;
  const sr=this.st.getBoundingClientRect();this.ox=sr.left-r.left;this.oy=sr.top-r.top}
 play(){this.t=0;if(this.on)return;this.on=true;let last=performance.now();const loop=n=>{this.t+=Math.min(64,n-last);last=n;this.draw();
   if(this.t>END&&!this.idle){this.on=false;return}
   if(this.t>END+2800*40&&!this.bg){this.on=false;return}requestAnimationFrame(loop)};requestAnimationFrame(loop)}
 draw(){if(!this.k)return;const{ctx,k}=this,t=this.t;ctx.setTransform(this.d,0,0,this.d,0,0);ctx.clearRect(0,0,this.cv.width,this.cv.height);
  const P=(X,Y)=>[this.ox+X*k,this.oy+Y*k];
  const star=(x,y,s,rot,col,a)=>{ctx.save();ctx.translate(x,y);ctx.rotate(rot);ctx.globalAlpha=a;ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(0,-s);const c=s*.14;ctx.quadraticCurveTo(c,-c,s,0);ctx.quadraticCurveTo(c,c,0,s);ctx.quadraticCurveTo(-c,c,-s,0);ctx.quadraticCurveTo(-c,-c,0,-s);ctx.fill();ctx.restore()};
  const g={line(x1,y1,x2,y2,col,a,w){const[a1,b1]=P(x1,y1),[a2,b2]=P(x2,y2);ctx.globalAlpha=a;ctx.strokeStyle=col;ctx.lineWidth=Math.max(.6,w*k);ctx.beginPath();ctx.moveTo(a1,b1);ctx.lineTo(a2,b2);ctx.stroke();ctx.globalAlpha=1},
   dot(X,Y,r,col,a){const[x,y]=P(X,Y);ctx.globalAlpha=a;ctx.fillStyle=col;ctx.beginPath();ctx.arc(x,y,Math.max(.5,r*k),0,7);ctx.fill();ctx.globalAlpha=1},
   ring(X,Y,r,col,a,w){const[x,y]=P(X,Y);ctx.globalAlpha=a;ctx.strokeStyle=col;ctx.lineWidth=Math.max(1,w*k*2);ctx.beginPath();ctx.arc(x,y,r*k,0,7);ctx.stroke();ctx.globalAlpha=1},
   burst(c,t,T,d,n){const q=pr(t,T,T+d);if(q<=0||q>=1)return;const e=E.out(q);this.ring(c[0],c[1],70+330*e,GOLD,.85*(1-q),5*(1-q)+.5);
    const R=rng(n*13),cols=['#FCB201','#FA019F','#018FFC','#01BBBB','#FF4F54','#FC8301'];for(let i=0;i<n;i++){const an=i/n*6.283+R()*.4,dd=90+(260+R()*120)*e;const[x,y]=P(c[0]+Math.cos(an)*dd,c[1]+Math.sin(an)*dd);star(x,y,(16+R()*12)*k*(1-q),q*3,cols[i%6],1-q)}}};
  if(this.net)drawNet(this.net,t,g);
  this.drawBg(t);
  const o=render(t,g,k);
  if(t>END&&this.idle){const i=(t-END)%2800,sp=o.spark||(o.spark={});sp.r=(sp.r||0)+90*E.io(pr(i,0,800));sp.s=(sp.s??1)*(1+.12*bump(i,0,800));
   const b=bump(i,350,650);if(b>0){const[x,y]=P(SL[0]+92,SL[1]-96);star(x,y,26*k*b,i/300,'#fff',b);star(x,y,16*k*b,i/300,GOLD,b)}}
  const put=(e,s={})=>{e.style.transform=`translate(${(s.x||0)*k}px,${(s.y||0)*k}px) rotate(${s.r||0}deg) scale(${(s.s??1)*(s.sx??1)},${(s.s??1)*(s.sy??1)})`;e.style.opacity=s.o??1;e.style.filter=s.f||''};
  for(const n of GROUP)put(this.el[n],o[n]);put(this.el.spark,o.spark)}
}
window.ScholaraLogoParts=PT;
if(!customElements.get('scholara-logo'))customElements.define('scholara-logo',ScholaraLogo);
if(!document.querySelector('link[rel~=icon]')){const l=document.createElement('link');l.rel='icon';l.href=PT.bookSpark.src;document.head.appendChild(l)}
})();
